CREATE OR REPLACE FUNCTION public.tenh_apply_approved_branch_plan()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_limit integer;
begin
  if new.status<>'approved' or old.status='approved' then return new; end if;
  if new.pricing_version in (5,6) then return new; end if;
  perform 1 from public.businesses where id=new.business_id for update;
  v_limit:=case when new.plan_key='custom' then new.requested_branch_limit else 1 end;
  if (select count(*) from public.business_locations where business_id=new.business_id and is_active)>v_limit then raise exception 'The payment plan has fewer branches than are active.'; end if;
  if (select count(*) from public.business_members where business_id=new.business_id and is_active)>new.requested_user_limit then raise exception 'The payment plan has fewer seats than are active.'; end if;
  update public.businesses
  set subscription_branch_limit=v_limit,
      subscription_base_plan_key=case when new.pricing_version=3 then null else coalesce(new.base_plan_key,case when new.plan_key='custom' then 'growth' else new.plan_key end) end
  where id=new.business_id;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.tenh_preserve_trial_time_after_paid_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b public.businesses%rowtype;
  v_activation_at timestamptz;
  v_target_expiry timestamptz;
begin
  if new.status <> 'approved'
     or old.status = 'approved'
     or coalesce(new.term_months, 0) <= 0
     or new.order_kind not in ('activation', 'upgrade') then
    return new;
  end if;

  select *
  into b
  from public.businesses
  where id = new.business_id
  for update;

  if not found
     or b.trial_started_at is null
     or b.trial_expires_at is null
     or new.created_at < b.trial_started_at
     or new.created_at >= b.trial_expires_at then
    return new;
  end if;

  v_activation_at := coalesce(new.approved_at, new.reviewed_at, now());
  v_target_expiry := greatest(b.trial_expires_at, v_activation_at)
    + make_interval(months => new.term_months);

  -- Never shorten an expiry if an approval procedure already preserved more
  -- time. This also makes the safety compatible with older/newer review RPCs.
  if b.subscription_expires_at is null
     or b.subscription_expires_at < v_target_expiry then
    update public.businesses
    set subscription_expires_at = v_target_expiry,
        updated_at = now()
    where id = b.id;
  end if;

  return new;
end;
$function$
